-- Phase 1. All objects are versioned; rollback is in supabase/rollbacks.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated, anon;
create extension if not exists unaccent with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create type public.app_role as enum ('admin','editor','comercial','fornecedor','sindico');
create table public.profiles(id uuid primary key references auth.users(id) on delete restrict,nome text not null check(length(nome) between 3 and 120),telefone text,cidade text,estado text,condominio_nome text,cargo text,ativo boolean not null default true,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table public.user_roles(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete restrict,role public.app_role not null,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),unique(user_id,role));
create table public.consentimentos(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete restrict,email text,documento text not null check(documento in ('termos','privacidade','cookies','newsletter')),versao text not null,aceito_em timestamptz not null default now(),origem text not null,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table public.audit_log(id uuid primary key default gen_random_uuid(),ator_id uuid references public.profiles(id) on delete restrict,acao text not null,tabela text not null,registro_id uuid,antes jsonb,depois jsonb,ip_hash text,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table public.configuracoes(id uuid primary key default gen_random_uuid(),chave text not null unique,valor jsonb not null,publica boolean not null default false,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table public.segmentos(id uuid primary key default gen_random_uuid(),nome text not null,slug text not null unique,icone text,ordem int not null default 0,ativo boolean not null default true,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table public.estados(id uuid primary key default gen_random_uuid(),uf text unique not null check(length(uf)=2),nome text not null,slug text unique not null,ibge_id int unique not null,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table public.cidades(id uuid primary key default gen_random_uuid(),uf text not null references public.estados(uf) on delete restrict,nome text not null,slug text not null,ibge_id int not null unique,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),unique(uf,slug));
-- Minimal supplier identity belongs to registration (phase 1). Expansion is gated by phase 2.
create table public.fornecedores(id uuid primary key default gen_random_uuid(),dono_id uuid not null unique references public.profiles(id) on delete restrict,nome_fantasia text not null,cnpj text not null unique,status text not null default 'rascunho' check(status in ('rascunho','em_analise','ajuste_solicitado','publicado','suspenso','recusado')),cadastro_em timestamptz not null default now(),criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create function private.has_role(uid uuid,requested public.app_role) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles r join public.profiles p on p.id=r.user_id where r.user_id=uid and r.role=requested and p.ativo)$$;
-- Safe public wrapper: query only the caller's own role, never arbitrary users.
create function public.has_role(uid uuid,role public.app_role) returns boolean language sql stable set search_path='' as $$select uid=auth.uid() and private.has_role(uid,role)$$;
create function private.is_active() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and ativo)$$;
create function private.valid_cnpj(value text) returns boolean language plpgsql immutable set search_path='' as $$declare d text:=regexp_replace(value,'\D','','g');s int;w int;v int;i int;len int;begin if length(d)<>14 or d=repeat(substr(d,1,1),14) then return false;end if;for len in 12..13 loop s:=0;w:=len-7;for i in 1..len loop s:=s+substr(d,i,1)::int*w;w:=case when w=2 then 9 else w-1 end;end loop;v:=case when s%11<2 then 0 else 11-s%11 end;if v<>substr(d,len+1,1)::int then return false;end if;end loop;return true;end$$;
alter table public.fornecedores add constraint cnpj_valido check(private.valid_cnpj(cnpj));
create function private.set_atualizado_em() returns trigger language plpgsql set search_path='' as $$begin new.atualizado_em=now();return new;end$$;
create function private.gravar_audit() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.audit_log(ator_id,acao,tabela,registro_id,antes,depois) values(auth.uid(),tg_op,tg_table_name,coalesce(new.id,old.id),case when tg_op<>'INSERT' then to_jsonb(old) end,case when tg_op<>'DELETE' then to_jsonb(new) end);return coalesce(new,old);end$$;
create function private.protect_admin() returns trigger language plpgsql set search_path='' as $$begin perform pg_advisory_xact_lock(451001);if tg_table_name='profiles' then if old.ativo and not new.ativo and exists(select 1 from public.user_roles where user_id=old.id and role='admin') and not exists(select 1 from public.user_roles r join public.profiles p on p.id=r.user_id where r.role='admin' and p.ativo and p.id<>old.id) then raise exception 'O último admin ativo não pode ser desativado';end if;return new;end if;if old.role='admin' and (tg_op='DELETE' or new.role<>'admin' or new.user_id<>old.user_id) and not exists(select 1 from public.user_roles r join public.profiles p on p.id=r.user_id where r.role='admin' and p.ativo and r.id<>old.id) then raise exception 'O último admin ativo não pode ser removido';end if;return coalesce(new,old);end$$;
create trigger protect_last_admin before update or delete on public.user_roles for each row execute function private.protect_admin();
create trigger protect_active_admin before update on public.profiles for each row execute function private.protect_admin();
create function private.protect_profile() returns trigger language plpgsql set search_path='' as $$begin if current_user in ('anon','authenticated') and not private.has_role(auth.uid(),'admin') and (new.ativo is distinct from old.ativo or new.id is distinct from old.id) then raise exception 'Campo protegido';end if;return new;end$$;
create trigger protect_profile_fields before update on public.profiles for each row execute function private.protect_profile();
create function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$declare m jsonb:=new.raw_user_meta_data;kind public.app_role;begin
if coalesce(m->>'tipo','') not in ('sindico','fornecedor') or coalesce(m->>'termos','false')<>'true' or coalesce(m->>'termos_versao','')='' or coalesce(m->>'privacidade_versao','')='' then raise exception 'Cadastro inválido: tipo e consentimentos obrigatórios';end if;
kind:=(m->>'tipo')::public.app_role;
if kind='sindico' and not exists(select 1 from public.cidades where uf=m->>'estado' and nome=m->>'cidade') then raise exception 'Cidade inválida';end if;
if kind='fornecedor' and (coalesce(m->>'empresa','')='' or length(regexp_replace(coalesce(m->>'telefone',''),'\D','','g')) not between 10 and 11) then raise exception 'Empresa e telefone obrigatórios';end if;
insert into public.profiles(id,nome,telefone,cidade,estado) values(new.id,m->>'nome',m->>'telefone',m->>'cidade',m->>'estado');
insert into public.user_roles(user_id,role) values(new.id,kind);
insert into public.consentimentos(user_id,documento,versao,origem) values(new.id,'termos',m->>'termos_versao','cadastro'),(new.id,'privacidade',m->>'privacidade_versao','cadastro');
if coalesce(m->>'newsletter','false')='true' then insert into public.consentimentos(user_id,documento,versao,origem) values(new.id,'newsletter',m->>'privacidade_versao','cadastro');end if;
if kind='fornecedor' then insert into public.fornecedores(dono_id,nome_fantasia,cnpj) values(new.id,m->>'empresa',regexp_replace(m->>'cnpj','\D','','g'));end if;return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();
do $$declare t text;begin foreach t in array array['profiles','user_roles','consentimentos','audit_log','configuracoes','segmentos','estados','cidades','fornecedores'] loop execute format('alter table public.%I enable row level security',t);execute format('create trigger set_atualizado_em before update on public.%I for each row execute function private.set_atualizado_em()',t);end loop;foreach t in array array['profiles','user_roles','consentimentos','configuracoes','segmentos','fornecedores'] loop execute format('create trigger gravar_audit after insert or update or delete on public.%I for each row execute function private.gravar_audit()',t);end loop;end$$;
create policy profiles_read on public.profiles for select to authenticated using(private.is_active() and (id=auth.uid() or private.has_role(auth.uid(),'admin')));
create policy profiles_update on public.profiles for update to authenticated using(private.is_active() and (id=auth.uid() or private.has_role(auth.uid(),'admin'))) with check(private.is_active() and (id=auth.uid() or private.has_role(auth.uid(),'admin')));
create policy roles_read on public.user_roles for select to authenticated using(private.is_active() and (user_id=auth.uid() or private.has_role(auth.uid(),'admin')));
create policy roles_admin on public.user_roles for all to authenticated using(private.has_role(auth.uid(),'admin')) with check(private.has_role(auth.uid(),'admin'));
create policy consent_admin on public.consentimentos for select to authenticated using(private.has_role(auth.uid(),'admin'));
create policy audit_admin on public.audit_log for select to authenticated using(private.has_role(auth.uid(),'admin'));
create policy config_read on public.configuracoes for select to anon,authenticated using(publica or private.has_role(auth.uid(),'admin'));
create policy config_admin on public.configuracoes for all to authenticated using(private.has_role(auth.uid(),'admin')) with check(private.has_role(auth.uid(),'admin'));
create policy segments_read on public.segmentos for select to anon,authenticated using(ativo or private.has_role(auth.uid(),'admin'));
create policy segments_admin on public.segmentos for all to authenticated using(private.has_role(auth.uid(),'admin')) with check(private.has_role(auth.uid(),'admin'));
create policy states_read on public.estados for select to anon,authenticated using(true);
create policy cities_read on public.cidades for select to anon,authenticated using(true);
create policy supplier_read on public.fornecedores for select to authenticated using(private.is_active() and (dono_id=auth.uid() or private.has_role(auth.uid(),'admin') or private.has_role(auth.uid(),'comercial')));
-- No browser writes to suppliers until the phase 2 state machine is implemented.
grant select,update on public.profiles to authenticated;
grant select,insert,update,delete on public.user_roles to authenticated;
grant select on public.consentimentos,public.audit_log,public.fornecedores to authenticated;
grant select on public.configuracoes,public.segmentos,public.estados,public.cidades to anon,authenticated;
grant insert,update on public.configuracoes,public.segmentos to authenticated;
revoke all on all functions in schema private from public;
grant execute on function private.has_role(uuid,public.app_role),private.is_active(),private.valid_cnpj(text) to anon,authenticated;
revoke all on function public.has_role(uuid,public.app_role) from public;
grant execute on function public.has_role(uuid,public.app_role) to authenticated;
create index profiles_ativo_idx on public.profiles(ativo);
create index consent_user_idx on public.consentimentos(user_id);
create index audit_actor_idx on public.audit_log(ator_id);
create index audit_date_idx on public.audit_log(criado_em);
create index cities_uf_idx on public.cidades(uf);
create index suppliers_status_idx on public.fornecedores(status);
create index suppliers_date_idx on public.fornecedores(cadastro_em);
